COPY supabase_migrations.schema_migrations (version, statements, name) FROM stdin;
20260329030922	{"-- Add columns that may be missing from waste_pickups\n  -- (ALTER TABLE ADD COLUMN IF NOT EXISTS is safe to run even if columns exist)\n\n  ALTER TABLE waste_pickups ADD COLUMN IF NOT EXISTS user_name text DEFAULT ''","ALTER TABLE waste_pickups ADD COLUMN IF NOT EXISTS user_phone text DEFAULT ''","ALTER TABLE waste_pickups ADD COLUMN IF NOT EXISTS scheduled_date timestamptz","ALTER TABLE waste_pickups ADD COLUMN IF NOT EXISTS scheduled_time text DEFAULT ''","ALTER TABLE waste_pickups ADD COLUMN IF NOT EXISTS assigned_to uuid REFERENCES auth.users(id)","ALTER TABLE waste_pickups ADD COLUMN IF NOT EXISTS assigned_driver_name text","ALTER TABLE waste_pickups ADD COLUMN IF NOT EXISTS notes text","ALTER TABLE waste_pickups ADD COLUMN IF NOT EXISTS reschedule_count integer DEFAULT 0","ALTER TABLE waste_pickups ADD COLUMN IF NOT EXISTS rescheduled_at timestamptz","ALTER TABLE waste_pickups ADD COLUMN IF NOT EXISTS updated_at timestamptz DEFAULT now()"}	add_pickup_columns
\.
